const item = $input.item;
const rawTitle = typeof item.json?.title === 'string' ? item.json.title.trim() : '';
const rawContent = typeof item.json?.content === 'string' ? item.json.content.trim() : '';

if (!rawContent) throw new Error('PDF content is required.');
if (rawContent.length > 12000) throw new Error('PDF content exceeds the 12,000-character teaching limit.');

function toAscii(value) {
  return value
    .replace(/[“”]/g, '"')
    .replace(/[‘’]/g, "'")
    .replace(/[–—]/g, '-')
    .replace(/…/g, '...')
    .replace(/[•●]/g, '-')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^\x20-\x7E\n]/g, '?');
}

function wrapLine(line, width = 86) {
  if (!line) return [''];
  const words = line.split(/\s+/);
  const wrapped = [];
  let current = '';
  for (const originalWord of words) {
    const chunks = originalWord.match(new RegExp(`.{1,${width}}`, 'g')) || [''];
    for (const word of chunks) {
      if (!current) current = word;
      else if (current.length + 1 + word.length <= width) current += ` ${word}`;
      else {
        wrapped.push(current);
        current = word;
      }
    }
  }
  if (current) wrapped.push(current);
  return wrapped;
}

function pdfEscape(value) {
  return value.replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');
}

const title = toAscii(rawTitle || 'Generated Summary').slice(0, 80);
const lines = toAscii(rawContent.replace(/\r\n?/g, '\n'))
  .split('\n')
  .flatMap((line) => wrapLine(line));
const linesPerPage = 42;
const pages = [];
for (let index = 0; index < lines.length; index += linesPerPage) {
  pages.push(lines.slice(index, index + linesPerPage));
}
if (pages.length === 0) pages.push([]);

const fontId = 3 + pages.length * 2;
const objects = [];
objects[1] = '<< /Type /Catalog /Pages 2 0 R >>';
const pageReferences = pages.map((_, index) => `${3 + index * 2} 0 R`).join(' ');
objects[2] = `<< /Type /Pages /Kids [${pageReferences}] /Count ${pages.length} >>`;

pages.forEach((pageLines, index) => {
  const pageId = 3 + index * 2;
  const contentId = pageId + 1;
  const pageTitle = pages.length > 1 ? `${title} (${index + 1}/${pages.length})` : title;
  const commands = [
    'BT',
    '/F1 18 Tf',
    '50 742 Td',
    `(${pdfEscape(pageTitle)}) Tj`,
    '/F1 11 Tf',
    '0 -28 Td',
  ];
  for (const line of pageLines) {
    commands.push(`(${pdfEscape(line)}) Tj`, '0 -15 Td');
  }
  commands.push('ET');
  const stream = `${commands.join('\n')}\n`;
  objects[pageId] = `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 ${fontId} 0 R >> >> /Contents ${contentId} 0 R >>`;
  objects[contentId] = `<< /Length ${Buffer.byteLength(stream, 'latin1')} >>\nstream\n${stream}endstream`;
});
objects[fontId] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>';

let pdf = '%PDF-1.4\n%\xE2\xE3\xCF\xD3\n';
const offsets = [0];
for (let id = 1; id <= fontId; id += 1) {
  offsets[id] = Buffer.byteLength(pdf, 'latin1');
  pdf += `${id} 0 obj\n${objects[id]}\nendobj\n`;
}
const xrefOffset = Buffer.byteLength(pdf, 'latin1');
pdf += `xref\n0 ${fontId + 1}\n`;
pdf += '0000000000 65535 f \n';
for (let id = 1; id <= fontId; id += 1) {
  pdf += `${String(offsets[id]).padStart(10, '0')} 00000 n \n`;
}
pdf += `trailer\n<< /Size ${fontId + 1} /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF\n`;

const slug = title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 48) || 'summary';
const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const fileName = `${slug}-${stamp}.pdf`;
const pdfBuffer = Buffer.from(pdf, 'latin1');
const binaryData = await this.helpers.prepareBinaryData(pdfBuffer, fileName, 'application/pdf');

return {
  json: { fileName, pageCount: pages.length, byteLength: pdfBuffer.length },
  binary: { data: binaryData }
};
